create or replace function spiritual.compute_prayer_times ( p_date date, p_lat numeric, p_lon numeric, p_tz text default 'UTC', p_fajr_angle numeric default 18.0, p_isha_angle numeric default 17.0, p_asr_method text default 'standard' ) returns jsonb language plpgsql stable as $$ declare d timestamptz := p_date::timestamptz; dec numeric; eot_min numeric; noon timestamptz; sunrise_ha numeric; asr_factor numeric; asr_angle numeric; duration_day interval; result jsonb; begin dec := spiritual.sun_declination(d); eot_min := spiritual.equation_of_time(d); noon := spiritual.solar_noon(d, p_lon); sunrise_ha := spiritual.hour_angle(p_lat, dec, -0.833); asr_factor := case when p_asr_method = 'hanafi' then 2.0 else 1.0 end; asr_angle := degrees(atan(asr_factor + tan(radians(abs(p_lat - dec))))); duration_day := interval '1 day' * (2 * sunrise_ha / 360.0); result := jsonb_build_object( 'date', p_date, 'latitude', p_lat, 'longitude', p_lon, 'method', jsonb_build_object('fajr_angle', p_fajr_angle, 'isha_angle', p_isha_angle, 'asr_method', p_asr_method), 'fajr', (noon - (spiritual.hour_angle(p_lat, dec, p_fajr_angle) / 360.0 * interval '1 day')::interval) at time zone p_tz, 'sunrise', (noon - (sunrise_ha / 360.0 * interval '1 day')::interval) at time zone p_tz, 'dhuhr', noon at time zone p_tz, 'asr', (noon + (spiritual.hour_angle(p_lat, dec, asr_angle) / 360.0 * interval '1 day')::interval) at time zone p_tz, 'maghrib', (noon + (sunrise_ha / 360.0 * interval '1 day')::interval) at time zone p_tz, 'isha', (noon + (spiritual.hour_angle(p_lat, dec, p_isha_angle) / 360.0 * interval '1 day')::interval) at time zone p_tz ); return result; end; $$;
